import java.util.Arrays;
import com.aerotopo.learning.SurveyAlgorithms;
public class DeduplicateSortedDemo {
    public static void main(String[] args) {
        int[] values = {1,1,2,2,2,4,4};
        int length = SurveyAlgorithms.deduplicateSorted(values);
        System.out.println("length=" + length);
        System.out.println(Arrays.toString(Arrays.copyOf(values,length)));
    }
}
